2	import assert from 'node:assert/strict';
3	import { roundCents, formatEuros, parseEuros } from '../src/money.js';
4	
5	test('roundCents rounds half to even', () => {
6	  assert.equal(roundCents(124.5), 124);
7	  assert.equal(roundCents(125.5), 126);
8	  assert.equal(roundCents(2.4), 2);
9	  assert.equal(roundCents(2.6), 3);
10	  assert.equal(roundCents(-0.5), 0);
11	});
12	
13	test('roundCents ignores binary noise', () => {
14	  assert.equal(roundCents(0.1 * 3 * 100), 30);
15	  assert.equal(roundCents(1.005 * 100), 100);
16	});
17	
18	test('formatEuros adds the sign, thousands separators and two decimals', () => {
19	  assert.equal(formatEuros(123456), '€1,234.56');
20	  assert.equal(formatEuros(5), '€0.05');
21	  assert.equal(formatEuros(-250), '-€2.50');
22	  assert.equal(formatEuros(100000000), '€1,000,000.00');
23	});
24	
25	test('parseEuros reads what people type', () => {
26	  assert.deepEqual(parseEuros('12'), { ok: true, value: 1200 });
27	  assert.deepEqual(parseEuros('12.5'), { ok: true, value: 1250 });
28	  assert.deepEqual(parseEuros('1,234.56'), { ok: true, value: 123456 });
29	  assert.deepEqual(parseEuros('12.345'), { ok: false, error: 'AMOUNT_INVALID' });
30	  assert.deepEqual(parseEuros('abc'), { ok: false, error: 'AMOUNT_INVALID' });
31	});
