// Currency tests

test('RATES constant exists with EUR, USD, GBP', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to EUR returns same amount', () => {
  assert.deepEqual(convert(100, 'EUR'), { ok: true, value: 100 });
  assert.deepEqual(convert(123456, 'EUR'), { ok: true, value: 123456 });
});

test('convert EUR to USD uses correct rate', () => {
  const result = convert(100, 'USD');
  assert.equal(result.ok, true);
  // 100 EUR cents = 1 EUR = 1.085 USD = 108.5 USD cents, rounds to 109
  assert.equal(result.value, 109);
});

test('convert EUR to GBP uses correct rate', () => {
  const result = convert(100, 'GBP');
  assert.equal(result.ok, true);
  // 100 EUR cents = 1 EUR = 0.8425 GBP = 84.25 GBP cents, rounds to 84
  assert.equal(result.value, 84);
});

test('convert unknown currency returns UNKNOWN_CURRENCY', () => {
  const result = convert(100, 'JPY');
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_CURRENCY' });
});

test('convert unknown currency (lowercase) returns UNKNOWN_CURRENCY', () => {
  const result = convert(100, 'usd');
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_CURRENCY' });
});

test('convert large amount EUR to USD', () => {
  // 123456 EUR cents = 1234.56 EUR = 1234.56 * 1.085 USD = 1339.39 USD ≈ 133939 USD cents
  const result = convert(123456, 'USD');
  assert.equal(result.ok, true);
  assert(result.value > 130000);
  assert(result.value < 140000);
});

test('convert zero amount', () => {
  assert.deepEqual(convert(0, 'EUR'), { ok: true, value: 0 });
  assert.deepEqual(convert(0, 'USD'), { ok: true, value: 0 });
  assert.deepEqual(convert(0, 'GBP'), { ok: true, value: 0 });
});

test('convert returns integer cents', () => {
  const result = convert(123, 'USD');
  assert.equal(result.ok, true);
  assert(Number.isInteger(result.value));
});

test('formatMoney EUR formats with euro symbol and thousands separator', () => {
  const result = formatMoney(123456, 'EUR');
  assert.deepEqual(result, { ok: true, value: '€1,234.56' });
});

test('formatMoney USD formats with dollar sign and thousands separator', () => {
  const result = formatMoney(123456, 'USD');
  assert.deepEqual(result, { ok: true, value: '$1,234.56' });
});

test('formatMoney GBP formats with pound sign and thousands separator', () => {
  const result = formatMoney(123456, 'GBP');
  assert.deepEqual(result, { ok: true, value: '£1,234.56' });
});

test('formatMoney small amount', () => {
  const result = formatMoney(5, 'USD');
  assert.deepEqual(result, { ok: true, value: '$0.05' });
});

test('formatMoney negative amount USD', () => {
  const result = formatMoney(-250, 'USD');
  assert.deepEqual(result, { ok: true, value: '-$2.50' });
});

test('formatMoney negative amount GBP', () => {
  const result = formatMoney(-250, 'GBP');
  assert.deepEqual(result, { ok: true, value: '-£2.50' });
});

test('formatMoney negative amount EUR', () => {
  const result = formatMoney(-250, 'EUR');
  assert.deepEqual(result, { ok: true, value: '-€2.50' });
});

test('formatMoney zero amount', () => {
  assert.deepEqual(formatMoney(0, 'EUR'), { ok: true, value: '€0.00' });
  assert.deepEqual(formatMoney(0, 'USD'), { ok: true, value: '$0.00' });
  assert.deepEqual(formatMoney(0, 'GBP'), { ok: true, value: '£0.00' });
});

test('formatMoney unknown currency returns UNKNOWN_CURRENCY', () => {
  const result = formatMoney(100, 'JPY');
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_CURRENCY' });
});

test('formatMoney large amount', () => {
  const result = formatMoney(100000000, 'USD');
  assert.deepEqual(result, { ok: true, value: '$1,000,000.00' });
});

test('formatMoney maintains 2 decimal places', () => {
  const result1 = formatMoney(100, 'EUR');
  assert(result1.value.endsWith('.00'));

  const result2 = formatMoney(1, 'USD');
  assert(result2.value.endsWith('.01'));

  const result3 = formatMoney(50, 'GBP');
  assert(result3.value.endsWith('.50'));
});

test('convert and format together: EUR to USD and back', () => {
  // Start with 100 EUR cents
  const usdResult = convert(100, 'USD');
  assert.equal(usdResult.ok, true);

  // Format as USD currency
  const formatted = formatMoney(usdResult.value, 'USD');
  assert.equal(formatted.ok, true);
  assert(formatted.value.startsWith('$'));
  assert(formatted.value.includes('.'));
});

test('convert consistency: multiple EUR to GBP conversions', () => {
  const r1 = convert(100, 'GBP');
  const r2 = convert(100, 'GBP');
  assert.deepEqual(r1, r2);
});

test('formatMoney with specific amounts', () => {
  // 12.34 USD = 1234 cents
  const result = formatMoney(1234, 'USD');
  assert.deepEqual(result, { ok: true, value: '$12.34' });
});

test('convert EUR 1.00 to all currencies', () => {
  const eur = convert(100, 'EUR');
  const usd = convert(100, 'USD');
  const gbp = convert(100, 'GBP');

  assert.equal(eur.value, 100);
  assert.equal(usd.value, 109); // 1.085 * 100 = 108.5 ≈ 109
  assert.equal(gbp.value, 84); // 0.8425 * 100 = 84.25 ≈ 84
});

test('formatMoney respects negative sign placement', () => {
  const usd = formatMoney(-100, 'USD');
  assert.equal(usd.value, '-$1.00');
  assert(usd.value.startsWith('-'));
});

test('RATES are positive', () => {
  assert(RATES.EUR > 0);
  assert(RATES.USD > 0);
  assert(RATES.GBP > 0);
});

test('convert rounds using banker\'s rounding', () => {
  // Test that convert uses roundCents logic
  // If we convert an amount that results in X.5, it should round to even
  const result = convert(184, 'GBP');
  assert.equal(result.ok, true);
  // 184 EUR cents = 1.84 EUR = 1.84 * 0.8425 = 1.5503 GBP = 155.03 GBP cents
  assert(result.value > 0);
  assert(Number.isInteger(result.value));
});

