1	import { ok, fail } from './result.js';
2	
3	/**
4	 * Round a (possibly fractional) number of cents to a whole cent, half to even (banker's rounding):
5	 * 124.5 -> 124, 125.5 -> 126, 2.4 -> 2, -0.5 -> 0.
6	 * @param {number} x
7	 * @returns {number}
8	 */
9	export function roundCents(x) {
10	  const r = Math.round(x * 1e6) / 1e6; // drop binary noise such as 124.49999999999999
11	  const floor = Math.floor(r);
12	  const diff = r - floor;
13	  if (diff > 0.5) return floor + 1;
14	  if (diff < 0.5) return floor === 0 ? 0 : floor;
15	  return floor % 2 === 0 ? floor : floor + 1;
16	}
17	
18	/**
19	 * Format cents as euros for people: 123456 -> "€1,234.56", -5 -> "-€0.05".
20	 * @param {number} cents
21	 * @returns {string}
22	 */
23	export function formatEuros(cents) {
24	  const sign = cents < 0 ? '-' : '';
25	  const abs = Math.abs(cents);
26	  const euros = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
27	  return `${sign}€${euros}.${String(abs % 100).padStart(2, '0')}`;
28	}
29	
30	/**
31	 * Parse a euro amount typed by a person ("12", "12.5", "1,234.56") into cents.
32	 * @param {string} text
33	 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
